def strategy(history, rng):
    n = len(history)

    # First move: cooperate.
    if n == 0:
        return 'C'

    # Count outcomes in current match.
    cc = cd = dc = dd = 0
    my_d = opp_d = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            my_d += 1
            if b == 'C':
                dc += 1
            else:
                dd += 1
        if b == 'D':
            opp_d += 1

    # Last few rounds matter more.
    last = history[-10:]
    last_opp_d = sum(1 for a, b in last if b == 'D')
    last_my_d = sum(1 for a, b in last if a == 'D')

    # If opponent is mostly cooperative, stay cooperative but punish recent betrayal.
    if opp_d <= n // 5:
        # Cooperate, unless opponent just defected in the immediately previous round.
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    # If opponent is heavily defective, exploit/defect as needed.
    if opp_d * 3 >= n * 2:
        # Defect mostly, but occasionally cooperate to probe for cooperation.
        # If opponent has just cooperated after long defection, reciprocate with C.
        if history[-1][1] == 'C':
            return 'C'
        # Small deterministic probing schedule favoring D.
        return 'D' if (n + cc + dc) % 7 != 0 else 'C'

    # Mixed case: use a forgiving but retaliatory scheme.
    # If opponent recently defected more than once in last 3, defect.
    recent_defections = 0
    for a, b in history[-3:]:
        if b == 'D':
            recent_defections += 1

    if recent_defections >= 2:
        return 'D'

    # If we have been defecting too much recently, try to restore cooperation.
    if last_my_d >= 6:
        return 'C'

    # Default: cooperate if mutual cooperation has been common.
    if cc >= cd + dc:
        return 'C'

    # Otherwise defect more often near the end of the match.
    remaining = 100 - n
    if remaining <= 10:
        # Endgame: defect unless opponent has been almost perfectly cooperative.
        if opp_d <= 2:
            return 'C'
        return 'D'

    # Use a cautious probabilistic mix based on opponent's defection rate.
    rate = opp_d / n
    if rng.random() < rate * 0.8:
        return 'D'
    return 'C'
